script:
(function() {
    setTimeout(() => {
        if (typeof frappe === 'undefined' || !root_element) return;

        if (frappe.session.user === "Administrator") {
            const container = root_element.querySelector('#hr-card-horizontal');
            if (container) {
                container.innerHTML = `<div class="admin-note">Admin view \u2014 check-in is disabled for this account.</div>`;
            }
            return;
        }

        let timerInterval;
        // clock-independent timer: anchor on the server's computed worked-seconds and
        // count up using the LOCAL elapsed time since that fetch. Never subtract a
        // server timestamp from the device clock (that goes negative if the phone/PC
        // clock/timezone is behind real time).
        let anchorSec = 0, anchorAt = 0, running = false;
        let currentEmpId = null;
        let isProcessing = false;
        let lastClickTime = 0;

        const getEl = (sel) => root_element.querySelector(sel);
        const setSafeText = (id, val) => {
            const el = getEl('#' + id);
            if (el) el.innerText = val;
        };

        // If the device date/time is set wrong (e.g. a laptop left on a foreign
        // timezone/clock), warn the user. Uses the server's HTTP Date header (real
        // UTC from the NTP-synced server), so it's timezone-proof.
        function checkClockSkew() {
            try {
                fetch(window.location.origin + "/api/method/frappe.ping", { method: "GET", cache: "no-store" })
                    .then((resp) => {
                        const d = resp.headers.get("Date");
                        if (!d) return;
                        const skewMin = Math.round((Date.now() - new Date(d).getTime()) / 60000);
                        if (Math.abs(skewMin) > 5) {
                            frappe.msgprint({
                                title: "Please fix your device clock",
                                message: "Your device's date & time look off by about " + Math.abs(skewMin) +
                                    " minutes versus the server. Please set your date, time and time zone to " +
                                    "<b>automatic</b>, then refresh this page — otherwise your work timer may display incorrectly.",
                                indicator: "orange"
                            });
                        }
                    }).catch(() => {});
            } catch (e) {}
        }
        checkClockSkew();

        const parseDateTime = (str) => {
            if (!str) return null;
            return new Date(str.replace(' ', 'T'));
        };

        function updateTimerDisplay(ms) {
            ms = Math.max(0, ms); // never show negative time
            const s = Math.floor(ms / 1000);
            setSafeText('hr-box', String(Math.floor(s / 3600)).padStart(2, '0'));
            setSafeText('min-box', String(Math.floor((s % 3600) / 60)).padStart(2, '0'));
            setSafeText('sec-box', String(s % 60).padStart(2, '0'));
        }

        function runTimer() {
            if (!running) return;
            const secs = anchorSec + Math.max(0, (Date.now() - anchorAt) / 1000);
            updateTimerDisplay(secs * 1000);
        }

        function startTimer() {
            if (!timerInterval) timerInterval = setInterval(runTimer, 1000);
            runTimer();
        }
        function stopTimer() {
            if (timerInterval) { clearInterval(timerInterval); timerInterval = null; }
        }

        // ========================
        // FETCH EMPLOYEE
        // ========================
        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Employee",
                filters: { user_id: frappe.session.user }
            },
            callback: (r) => {
                if (r.message) {
                    const emp = r.message;
                    currentEmpId = emp.name;
                    setSafeText('user-name', emp.employee_name);
                    setSafeText('user-desig', emp.designation || "Team Member");

                    const imgEl = getEl('#user-img');
                    if (imgEl) {
                        if (emp.image) {
                            imgEl.src = emp.image;
                        } else {
                            // fall back to the user's profile photo if the Employee record has none
                            frappe.call({
                                method: "frappe.client.get_value",
                                args: { doctype: "User", filters: { name: frappe.session.user }, fieldname: "user_image" },
                                callback: (ur) => {
                                    if (ur.message && ur.message.user_image) imgEl.src = ur.message.user_image;
                                }
                            });
                        }
                    }

                    fetchTodayStatus(emp.name);
                    loadWorkingHours();
                } else {
                    setSafeText('user-name', "Not Linked");
                    setSafeText('user-desig', "No Employee record");
                    setSafeText('checkin-status', "—");
                }
            }
        });

        // ========================
        // FETCH CHECKIN STATUS  (button label + status text only)
        // ========================
        function fetchTodayStatus(emp_id) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Employee Checkin",
                    filters: {
                        employee: emp_id,
                        time: ['>=', frappe.datetime.get_today()]
                    },
                    fields: ['log_type', 'time', 'device_id'],
                    order_by: 'time asc',
                    limit: 100
                },
                callback: (res) => {
                    const btn = getEl('#main-checkin-btn');
                    const statusEl = getEl('#checkin-status');
                    const logs = res.message || [];

                    const lastLog = logs[logs.length - 1];
                    const isIn = lastLog && lastLog.log_type === 'IN';

                    if (isIn) {
                        const tag = lastLog.device_id || "Active";
                        statusEl.innerText = "Shift Active • " + tag;
                        statusEl.dataset.tone = "ok";
                        btn.innerText = "Check Out";
                        btn.dataset.state = "out";
                        btn.disabled = false;
                    } else {
                        const hadActivity = logs.length > 0;
                        statusEl.innerText = hadActivity ? "Shift Ended" : "Yet to Check-in";
                        statusEl.dataset.tone = hadActivity ? "warn" : "danger";
                        btn.innerText = "Check In";
                        btn.dataset.state = "in";
                        btn.disabled = false;
                    }

                    isProcessing = false;
                    // the running timer is driven by loadWorkingHours (server worked-seconds)
                    loadWorkingHours();
                },
                error: () => {
                    // if the status refresh fails, still release the button
                    isProcessing = false;
                    const b = getEl('#main-checkin-btn');
                    if (b) { b.disabled = false; }
                }
            });
        }

        // ========================
        // WORKING HOURS  (authoritative worked-seconds from the server)
        // ========================
        function loadWorkingHours() {
            frappe.call({
                method: "get_today_working_hours",
                callback: function(r) {
                    if (!r.message) return;
                    const data = r.message;

                    const el = getEl('#work-hours-display');
                    if (el) {
                        el.innerText = "Today  " + data.worked + "  /  " + data.required;
                        // tone is styled in CSS; data.color is green|orange|red
                        el.dataset.tone = data.color || "neutral";
                    }

                    // anchor the live timer (clock-independent)
                    anchorSec = data.worked_seconds || 0;
                    anchorAt = Date.now();
                    running = !!data.is_checked_in;
                    if (running) {
                        startTimer();
                    } else {
                        stopTimer();
                        updateTimerDisplay(anchorSec * 1000);
                    }
                }
            });
        }

        setInterval(loadWorkingHours, 60000);




        // ========================
        // CHECKIN BUTTON
        // ========================
        function handleCheckin() {
            const now = Date.now();
            if (now - lastClickTime < 2000) return;
            if (isProcessing) return;

            lastClickTime = now;
            isProcessing = true;

            const self = getEl('#main-checkin-btn');
            if (self && self.disabled) { isProcessing = false; return; }

            if (!navigator.geolocation) {
                frappe.msgprint({
                    title: "Location Required",
                    message: "Your browser does not support geolocation. Please use Chrome or Firefox.",
                    indicator: "red"
                });
                isProcessing = false;
                return;
            }

            self.disabled = true;
            self.innerText = "Getting Location...";

            navigator.geolocation.getCurrentPosition(
                (pos) => {
                    // --- Reject imprecise location fixes (IP/WiFi fallback) that cause false "Work From Home".
                    const MAX_ACCURACY_M = 200;
                    const acc = pos.coords.accuracy;
                    if (acc == null || acc > MAX_ACCURACY_M) {
                        frappe.msgprint({
                            title: "Location Not Precise Enough",
                            message: "We couldn't confirm your location precisely (accuracy ~" + Math.round(acc || 0) + " m). Please turn on precise GPS / Location and try again, or check in from your mobile phone.",
                            indicator: "orange"
                        });
                        self.disabled = false;
                        self.innerText = "Check In / Out";
                        isProcessing = false;
                        return;
                    }

                    self.innerText = "Processing...";

                    frappe.call({
                        method: "custom_toggle_checkin",
                        args: {
                            latitude: pos.coords.latitude,
                            longitude: pos.coords.longitude,
                            accuracy: acc
                        },
                        callback: (r) => {
                            isProcessing = false;
                            self.disabled = false;
                            if (r.message && r.message.status === "success") {
                                const m = r.message;
                                frappe.show_alert({
                                    message: (m.log_type === 'IN' ? 'Checked In' : 'Checked Out') + " — " + m.location_type,
                                    indicator: m.log_type === 'IN' ? 'green' : 'orange'
                                }, 5);
                                fetchTodayStatus(currentEmpId);
                            } else {
                                self.innerText = "Check In / Out";
                                frappe.msgprint(
                                    r.message && r.message.error
                                        ? r.message.error
                                        : "Check-in failed. Please try again."
                                );
                            }
                        },
                        error: () => {
                            isProcessing = false;
                            self.disabled = false;
                            self.innerText = "Check In / Out";
                            frappe.show_alert({ message: "Something went wrong. Please try again.", indicator: "red" }, 5);
                        }
                    });
                },
                (err) => {
                    const messages = {
                        1: "Location permission was denied. Please enable location access in your browser settings.",
                        2: "Location could not be determined. Please check your GPS or network.",
                        3: "Location request timed out. Please try again in an open area."
                    };
                    frappe.msgprint({
                        title: "Location Error",
                        message: messages[err.code] || "Location access failed.",
                        indicator: "red"
                    });
                    self.disabled = false;
                    self.innerText = "Check In / Out";
                    isProcessing = false;
                },
                {
                    enableHighAccuracy: true,
                    timeout: 15000,
                    maximumAge: 0
                }
            );
        }

        const btn = getEl('#main-checkin-btn');
        if (btn) {
            btn.onclick = handleCheckin;
        }

    }, 800);
})();


// --- pre-shift reminder opt-in ---------------------------------------------
// Employees have no write access to their own Employee doctype, so the
// preference is read/written through a whitelisted method that only ever
// touches the caller's own record and only this one field.
(function () {
    var wrap = root_element.querySelector('#lv-prenotif');
    var box = root_element.querySelector('#lv-prenotif-box');
    if (!wrap || !box) return;
    frappe.call({
        method: 'logikview_hr.reminders.get_shift_reminder_preference',
        callback: function (r) {
            var m = r.message || {};
            if (!m.available) return;          // e.g. admin with no employee record
            box.checked = !!m.enabled;
            wrap.hidden = false;
        }
    });
    box.addEventListener('change', function () {
        var want = box.checked;
        box.disabled = true;
        frappe.call({
            method: 'logikview_hr.reminders.set_shift_reminder_preference',
            args: { enabled: want ? 1 : 0 },
            callback: function (r) {
                box.disabled = false;
                var on = r.message && r.message.enabled;
                box.checked = !!on;
                frappe.show_alert({
                    message: on ? 'Pre-shift reminders on' : 'Pre-shift reminders off',
                    indicator: on ? 'green' : 'gray'
                }, 3);
            },
            error: function () { box.disabled = false; box.checked = !want; }
        });
    });
})();

style:
/* Logikview HR - shared block tokens.
   Each dashboard block renders in its own shadow root, so these tokens are
   repeated per block by design; there is no shared stylesheet to inherit from.
   Fonts come from the document-level app_include_css (font faces are not
   shadow-scoped), with a system fallback if that fails to load. */
:host { display: block; }
*, *::before, *::after { box-sizing: border-box; }

.lv {
	--navy: #4d4948;
	--navy-700: #3a3736;
	--navy-50: #f4f1ee;
	--amber: #d98d0e;
	--amber-50: #fdf5e2;

	--ink: #221f1e;
	--ink-70: #4a4441;
	--ink-60: #5c5551;
	--ink-40: #928a85;
	--line: #e7e2dc;
	--line-soft: #f1ede8;
	--surface: #ffffff;

	--ok: #17794f;      --ok-bg: #e7f5ee;
	--warn: #a86412;    --warn-bg: #fdf5e2;
	--danger: #b3261e;  --danger-bg: #fdecea;
	--info: #4d4948;    --info-bg: #f4f1ee;
	--violet: #5b43c9;  --violet-bg: #eeeaff;

	--r-xl: 18px;
	--r-lg: 14px;
	--r-md: 10px;
	--r-sm: 7px;

	--sh-1: 0 1px 2px rgba(16,32,48,.05);
	--sh-2: 0 4px 16px rgba(16,32,48,.07), 0 1px 3px rgba(16,32,48,.04);
	--sh-3: 0 16px 40px rgba(16,32,48,.12);

	--fs-display: 'Fraunces', Georgia, serif;
	--fs-body: 'Manrope', ui-sans-serif, system-ui, -apple-system, sans-serif;
	--fs-mono: 'JetBrains Mono', ui-monospace, Menlo, monospace;

	font-family: var(--fs-body);
	color: var(--ink);
	-webkit-font-smoothing: antialiased;
	max-width: 1180px;
	margin: 10px 0;
	font-variant-numeric: tabular-nums;
}

/* --- shared card shell ------------------------------------------------- */
.card {
	position: relative;
	background: var(--surface);
	border: 1px solid var(--line);
	border-radius: var(--r-xl);
	box-shadow: var(--sh-2);
	overflow: hidden;
}

.card__head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 12px;
	flex-wrap: wrap;
	padding: 16px 20px 13px;
	border-bottom: 1px solid var(--line-soft);
}

.card__title {
	margin: 0;
	font-family: var(--fs-display);
	font-size: 17px;
	font-weight: 500;
	letter-spacing: -0.005em;
	color: var(--ink);
}

.card__sub {
	margin: 3px 0 0;
	font-size: 11.5px;
	color: var(--ink-40);
	letter-spacing: 0.01em;
}

.card__body { padding: 16px 20px 18px; }

.link {
	font-size: 12px;
	font-weight: 700;
	color: var(--navy);
	text-decoration: none;
	white-space: nowrap;
	border-bottom: 1px solid transparent;
	transition: border-color .15s ease, color .15s ease;
}
.link:hover { color: var(--navy-700); border-bottom-color: currentColor; }

.muted { color: var(--ink-40); font-size: 12.5px; }

/* --- pills ------------------------------------------------------------- */
.pill {
	display: inline-flex;
	align-items: center;
	gap: 5px;
	padding: 3px 10px;
	border-radius: 999px;
	font-size: 11px;
	font-weight: 700;
	letter-spacing: .02em;
	background: var(--navy-50);
	color: var(--navy);
	white-space: nowrap;
}
.pill[data-tone="ok"]      { background: var(--ok-bg);     color: var(--ok); }
.pill[data-tone="warn"]    { background: var(--warn-bg);   color: var(--warn); }
.pill[data-tone="danger"]  { background: var(--danger-bg); color: var(--danger); }
.pill[data-tone="info"]    { background: var(--info-bg);   color: var(--info); }
.pill[data-tone="violet"]  { background: var(--violet-bg); color: var(--violet); }
.pill[data-tone="neutral"] { background: #f4f1ee;          color: var(--ink-60); }

/* --- entrance ---------------------------------------------------------- */
@keyframes lv-rise {
	from { opacity: 0; transform: translateY(6px); }
	to   { opacity: 1; transform: none; }
}
.rise { animation: lv-rise .42s cubic-bezier(.2,.7,.3,1) both; }

@media (prefers-reduced-motion: reduce) {
	.rise { animation: none; }
	* { transition: none !important; }
}

/* --- hero check-in card ------------------------------------------------ */
.hero {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 24px;
	flex-wrap: wrap;
	padding: 22px 26px;
	background: var(--surface);
	border: 1px solid var(--line);
	border-radius: var(--r-xl);
	box-shadow: var(--sh-2);
	overflow: hidden;
}

/* brand hairline: navy bleeding into the logo amber */
.hero__accent {
	position: absolute;
	inset: 0 0 auto 0;
	height: 3px;
	background: linear-gradient(90deg, var(--navy) 0%, var(--navy) 42%, var(--amber) 100%);
}

/* soft corner wash so the card has depth without a heavy fill */
.hero__wash {
	position: absolute;
	right: -120px;
	top: -160px;
	width: 420px;
	height: 420px;
	border-radius: 50%;
	background: radial-gradient(circle, rgba(77,73,72,.07) 0%, rgba(77,73,72,0) 68%);
	pointer-events: none;
}

.hero__identity {
	display: flex;
	align-items: center;
	gap: 18px;
	min-width: 0;
	position: relative;
}

.avatar {
	position: relative;
	flex: 0 0 74px;
	width: 74px;
	height: 74px;
	border-radius: 50%;
	padding: 3px;
	background: linear-gradient(140deg, var(--navy) 0%, #3f7fb5 55%, var(--amber) 100%);
	display: block;
}
.avatar img {
	width: 100%;
	height: 100%;
	object-fit: cover;
	border-radius: 50%;
	display: block;
	background: #e9eef4;
	border: 2px solid #fff;
}

.identity { min-width: 0; display: block; }

.identity__name {
	margin: 0;
	font-family: var(--fs-display);
	font-size: 25px;
	font-weight: 500;
	line-height: 1.15;
	letter-spacing: -0.015em;
	color: var(--ink);
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.identity__role {
	margin: 3px 0 0;
	font-size: 13.5px;
	font-weight: 500;
	color: var(--ink-60);
}

/* status line - tone set by the script via data-tone */
.status {
	margin: 10px 0 0;
	display: inline-flex;
	align-items: center;
	gap: 7px;
	font-size: 11px;
	font-weight: 800;
	text-transform: uppercase;
	letter-spacing: .07em;
	color: var(--ink-40);
}
.status::before {
	content: "";
	width: 7px;
	height: 7px;
	border-radius: 50%;
	background: currentColor;
	flex: 0 0 7px;
}
.status[data-tone="ok"]     { color: var(--ok); }
.status[data-tone="warn"]   { color: var(--warn); }
.status[data-tone="danger"] { color: var(--danger); }

/* live pulse only while the shift is actually running */
.status[data-tone="ok"]::before {
	animation: lv-pulse 2s ease-in-out infinite;
}
@keyframes lv-pulse {
	0%, 100% { box-shadow: 0 0 0 0 rgba(23,121,79,.45); }
	50%      { box-shadow: 0 0 0 5px rgba(23,121,79,0); }
}

/* --- right-hand console ------------------------------------------------ */
.hero__console {
	display: flex;
	flex-direction: column;
	align-items: flex-end;
	gap: 9px;
	position: relative;
}

.clock {
	display: inline-flex;
	align-items: baseline;
	gap: 1px;
	font-family: var(--fs-mono);
	font-size: 30px;
	font-weight: 700;
	line-height: 1;
	letter-spacing: -0.02em;
	color: var(--ink);
	font-variant-numeric: tabular-nums;
	padding: 9px 15px;
	border-radius: var(--r-md);
	background: linear-gradient(180deg, #f7fafc 0%, #f4f1ee 100%);
	border: 1px solid var(--line);
}
.clock i {
	font-style: normal;
	color: var(--ink-40);
	margin: 0 1px;
	animation: lv-blink 2s steps(1, end) infinite;
}
@keyframes lv-blink { 0%, 60% { opacity: 1; } 80%, 100% { opacity: .35; } }

.worked {
	font-size: 12.5px;
	font-weight: 700;
	letter-spacing: .01em;
	color: var(--ink-40);
	min-height: 16px;
}
.worked[data-tone="green"]  { color: var(--ok); }
.worked[data-tone="orange"] { color: var(--warn); }
.worked[data-tone="red"]    { color: var(--danger); }

.btn {
	appearance: none;
	border: 0;
	cursor: pointer;
	font-family: var(--fs-body);
	font-size: 13.5px;
	font-weight: 700;
	letter-spacing: .01em;
	color: #fff;
	padding: 11px 30px;
	border-radius: var(--r-md);
	background: var(--navy);
	box-shadow: 0 2px 8px rgba(77,73,72,.28);
	transition: transform .14s ease, box-shadow .14s ease, background .14s ease, opacity .14s ease;
}
.btn:hover:not(:disabled) {
	transform: translateY(-1px);
	box-shadow: 0 6px 18px rgba(77,73,72,.34);
}
.btn:active:not(:disabled) { transform: translateY(0); }
.btn:focus-visible { outline: 3px solid rgba(77,73,72,.35); outline-offset: 2px; }
.btn:disabled { opacity: .55; cursor: not-allowed; box-shadow: none; }

/* checked in -> the action is to leave, so the button reads as the exit */
.btn[data-state="out"] {
	background: #b3261e;
	box-shadow: 0 2px 8px rgba(179,38,30,.28);
}
.btn[data-state="out"]:hover:not(:disabled) { box-shadow: 0 6px 18px rgba(179,38,30,.34); }

.admin-note {
	padding: 14px 4px;
	font-size: 13px;
	color: var(--ink-40);
}

@media (max-width: 720px) {
	.hero { padding: 20px; gap: 18px; }
	.hero__identity { width: 100%; }
	.hero__console { width: 100%; align-items: stretch; }
	.clock { justify-content: center; font-size: 26px; }
	.worked { text-align: center; }
	.btn { width: 100%; }
	.identity__name { white-space: normal; }
}


/* --- lv accent identity ------------------------------------------------
   Colour-only layer on top of the existing card system: a gradient spine
   across the top of the card, a faint wash behind the header, and a hover
   lift tinted with the same hue. Every card used to be an identical white
   rectangle, which made a column of them read as one grey slab.
   Typography, spacing and layout are untouched.
   Named --lv-card-accent (not --accent) because two blocks already use
   --accent for their own internal purposes. */
.lv { --lv-card-accent: #4d4948; }

.card {
	transition: transform .2s cubic-bezier(.2,.7,.3,1),
	            box-shadow .2s ease,
	            border-color .2s ease;
}

.card::before {
	content: "";
	position: absolute;
	top: 0; left: 0; right: 0;
	height: 3px;
	background: linear-gradient(90deg,
		var(--lv-card-accent),
		color-mix(in srgb, var(--lv-card-accent) 32%, transparent) 70%,
		transparent);
	z-index: 2;
}

.card__head {
	background: linear-gradient(180deg,
		color-mix(in srgb, var(--lv-card-accent) 7%, #fff),
		#fff);
}

.card:hover {
	border-color: color-mix(in srgb, var(--lv-card-accent) 26%, var(--line));
	box-shadow:
		0 14px 34px color-mix(in srgb, var(--lv-card-accent) 15%, transparent),
		0 2px 8px rgba(16,32,48,.05);
}

@media (prefers-reduced-motion: reduce) {
	.card { transition: none; }
}


/* --- pre-shift reminder opt-in ----------------------------------------
   Employees cannot edit their own Employee record, so this is where they
   manage the optional advance reminders. The forgot-to-check-in/out ones
   are not shown here because they are not optional. */
.prenotif {
	display: flex;
	align-items: center;
	gap: 7px;
	margin-top: 9px;
	font-size: 11.5px;
	color: var(--ink-60);
	cursor: pointer;
	user-select: none;
}
.prenotif input {
	width: 13px; height: 13px;
	accent-color: var(--navy);
	cursor: pointer;
	margin: 0;
}
.prenotif:hover { color: var(--ink); }


/* --- brand hero ---------------------------------------------------------
   The check-in card is the largest thing on Home, so it is what makes the
   desk look branded or not. Charcoal field with gold as the action colour,
   straight off the logo. Gold cannot carry text on white (1.6:1) but gold
   BEHIND charcoal text is 9.8:1, so the primary button uses it that way. */
.hero {
	background: linear-gradient(135deg, #4d4948 0%, #3a3736 58%, #2b2827 100%);
	border-color: #3a3736;
	box-shadow: 0 14px 34px rgba(34,31,30,.20), 0 2px 8px rgba(34,31,30,.10);
}
.hero__accent {
	height: 4px;
	background: linear-gradient(90deg, #f8c300 0%, #f8c300 38%, #d98d0e 100%);
}
.hero__wash {
	background: radial-gradient(circle, rgba(248,195,0,.16) 0%, rgba(248,195,0,0) 68%);
}

/* type on the dark field */
.identity__name { color: #ffffff; }
.identity__role { color: #cfc7c1; }
.status         { color: #e8e1da; }

/* clock: dark panel, gold digits */
.clock {
	background: rgba(255,255,255,.06);
	border-color: rgba(255,255,255,.16);
	color: #f8c300;
}
.worked { color: #e8e1da; }

/* primary action in brand gold - charcoal text on gold reads at 9.8:1 */
.btn {
	background: #f8c300;
	color: #221f1e;
	box-shadow: 0 3px 12px rgba(248,195,0,.34);
}
.btn:hover { background: #ffd227; }

.avatar { border-color: rgba(248,195,0,.55); }

/* the opt-in checkbox sits on the dark field now */
.prenotif { color: #cfc7c1; }
.prenotif:hover { color: #ffffff; }
.prenotif input { accent-color: #f8c300; }

script:
(function () {
  setTimeout(function () {
    if (typeof frappe === 'undefined' || !root_element) return;
    var root = root_element;
    var monthEl = root.querySelector('#att-month');
    var gridEl = root.querySelector('#att-grid');
    var wdEl = root.querySelector('#att-weekdays');
    var legendEl = root.querySelector('#att-legend');
    if (!gridEl) return;

    var COLORS = {
      present: { bg: '#e7f8ef', dot: '#27ae60', label: 'Present (Office)' },
      wfh:     { bg: '#e8f1fd', dot: '#2f80ed', label: 'Work From Home' },
      half:    { bg: '#f4ecfd', dot: '#9b51e0', label: 'Half Day' },
      leave:   { bg: '#fff8e1', dot: '#f2c94c', label: 'Leave' },
      absent:  { bg: '#fdeaea', dot: '#e74c3c', label: 'Absent' },
      off:     { bg: '#fbfcfd', dot: '#ffffff', label: 'Weekly-off / Holiday' }
    };
    ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(function (d) {
      var c = document.createElement('div'); c.innerText = d; wdEl.appendChild(c);
    });
    var legendKeys = ['present','wfh','half','leave','absent','off'];
    legendKeys.forEach(function (k) {
      var it = document.createElement('div');
      it.className = 'cal-legend__item';
      it.innerHTML = '<span class="cal-legend__swatch" style="background:' + COLORS[k].dot + '"></span>' + COLORS[k].label;
      legendEl.appendChild(it);
    });

    var view = new Date(); view.setDate(1);
    var empId = null;
    var today = new Date(); today.setHours(0, 0, 0, 0);

    function fmt(d) {
      return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    }
    function getList(dt, filters, fields) {
      return new Promise(function (res) {
        frappe.call({
          method: 'frappe.client.get_list',
          args: { doctype: dt, filters: filters, fields: fields, limit_page_length: 0 },
          callback: function (r) { res((r && r.message) || []); },
          error: function () { res([]); }
        });
      });
    }

    frappe.call({
      method: 'frappe.client.get_value',
      args: { doctype: 'Employee', filters: { user_id: frappe.session.user }, fieldname: 'name' },
      callback: function (r) {
        if (r.message && r.message.name) { empId = r.message.name; render(); }
        else { monthEl.innerText = 'No employee linked to your account'; }
      }
    });

    function render() {
      monthEl.innerText = view.toLocaleString('default', { month: 'long', year: 'numeric' });
      var start = new Date(view.getFullYear(), view.getMonth(), 1);
      var end = new Date(view.getFullYear(), view.getMonth() + 1, 0);
      var s = fmt(start), e = fmt(end);
      Promise.all([
        new Promise(function (res) {
          frappe.call({ method: 'get_my_holidays', args: { from_date: s, to_date: e },
                        callback: function (r) { res(r.message || []); },
                        error: function () { res([]); } });
        }),
        getList('Attendance', { employee: empId, attendance_date: ['between', [s, e]] }, ['attendance_date', 'status', 'working_hours']),
        getList('Employee Checkin', { employee: empId, time: ['between', [s + ' 00:00:00', e + ' 23:59:59']] }, ['time', 'device_id'])
      ]).then(function (out) {
        var holidays = out[0], att = out[1], checkins = out[2];
        var holidayBy = {};
        holidays.forEach(function (h) { if (!h.weekly_off) holidayBy[h.date] = h.description || 'Holiday'; });
        var map = {};
        att.forEach(function (a) {
          var m = (map[a.attendance_date] = map[a.attendance_date] || {});
          m.status = a.status;
          m.hours = a.working_hours;
        });
        checkins.forEach(function (c) {
          var d = String(c.time).slice(0, 10);
          var m = (map[d] = map[d] || {});
          if (c.device_id === 'Work From Home') m.wfh = true;
          else if (c.device_id === 'Office') m.office = true;
        });
        draw(start, end, map, holidayBy);
      });
    }

    function classify(dateObj, info, isHoliday) {
      var isWeekend = (dateObj.getDay() === 0 || dateObj.getDay() === 6);
      var st = info && info.status;
      if (st === 'On Leave') return 'leave';
      if (st === 'Absent') return 'absent';
      if (st === 'Half Day') return 'half';
      if (st === 'Present' || st === 'Work From Home') {
        if (info.wfh) return 'wfh';
        return 'present';
      }
      if (info && (info.office || info.wfh)) return info.wfh && !info.office ? 'wfh' : 'present';
      if (isHoliday) return 'off';
      if (isWeekend) return 'off';
      if (dateObj < today) return 'absent';
      return null; // future working day, no data
    }

    function draw(start, end, map, holidayBy) {
      holidayBy = holidayBy || {};
      gridEl.innerHTML = '';
      var lead = start.getDay();
      for (var i = 0; i < lead; i++) gridEl.appendChild(document.createElement('div'));
      var days = end.getDate();
      for (var day = 1; day <= days; day++) {
        var dObj = new Date(view.getFullYear(), view.getMonth(), day);
        var key = fmt(dObj);
        var info = map[key];
        var holidayName = holidayBy[key];
        var kind = classify(dObj, info, !!holidayName);
        var cell = document.createElement('div');
        var isToday = (dObj.getTime() === today.getTime());
        cell.className = 'cal-cell';
        if (kind) cell.dataset.kind = kind;
        if (isToday) cell.dataset.today = '1';
        var num = document.createElement('div');
        num.innerText = day;
        num.className = 'cal-cell__num';
        cell.appendChild(num);
        if (kind) {
          var dot = document.createElement('span');
          dot.className = 'cal-cell__dot';
          cell.appendChild(dot);
          cell.title = holidayName ? holidayName : COLORS[kind].label;
        }
        // holiday name on the day itself - it used to be a hover tooltip only,
        // so on a wall of numbered cells there was nothing to say WHY a day
        // was off. Truncation is handled in CSS so long names don't reflow.
        if (holidayName) {
          var hn = document.createElement('div');
          hn.innerText = holidayName;
          hn.className = 'cal-cell__hol';
          hn.title = holidayName;
          cell.appendChild(hn);
        }
        // worked hours on days that were actually worked
        var hrs = info && info.hours;
        if (hrs && ['present', 'wfh', 'half'].indexOf(kind) !== -1) {
          var h = Math.floor(hrs), m = Math.round((hrs - h) * 60);
          if (m === 60) { h += 1; m = 0; }
          var hEl = document.createElement('div');
          hEl.innerText = h + ':' + (m < 10 ? '0' + m : m);
          hEl.className = 'cal-cell__hrs';
          cell.appendChild(hEl);
          cell.title = COLORS[kind].label + ' \u2022 ' + h + 'h ' + m + 'm worked';
        }
        gridEl.appendChild(cell);
      }
    }

    root.querySelector('#att-prev').onclick = function () { view.setMonth(view.getMonth() - 1); render(); };
    root.querySelector('#att-next').onclick = function () { view.setMonth(view.getMonth() + 1); render(); };
  }, 400);
})();

style:
/* Logikview HR - shared block tokens.
   Each dashboard block renders in its own shadow root, so these tokens are
   repeated per block by design; there is no shared stylesheet to inherit from.
   Fonts come from the document-level app_include_css (font faces are not
   shadow-scoped), with a system fallback if that fails to load. */
:host { display: block; }
*, *::before, *::after { box-sizing: border-box; }

.lv {
	--navy: #4d4948;
	--navy-700: #3a3736;
	--navy-50: #f4f1ee;
	--amber: #d98d0e;
	--amber-50: #fdf5e2;

	--ink: #221f1e;
	--ink-70: #4a4441;
	--ink-60: #5c5551;
	--ink-40: #928a85;
	--line: #e7e2dc;
	--line-soft: #f1ede8;
	--surface: #ffffff;

	--ok: #17794f;      --ok-bg: #e7f5ee;
	--warn: #a86412;    --warn-bg: #fdf5e2;
	--danger: #b3261e;  --danger-bg: #fdecea;
	--info: #4d4948;    --info-bg: #f4f1ee;
	--violet: #5b43c9;  --violet-bg: #eeeaff;

	--r-xl: 18px;
	--r-lg: 14px;
	--r-md: 10px;
	--r-sm: 7px;

	--sh-1: 0 1px 2px rgba(16,32,48,.05);
	--sh-2: 0 4px 16px rgba(16,32,48,.07), 0 1px 3px rgba(16,32,48,.04);
	--sh-3: 0 16px 40px rgba(16,32,48,.12);

	--fs-display: 'Fraunces', Georgia, serif;
	--fs-body: 'Manrope', ui-sans-serif, system-ui, -apple-system, sans-serif;
	--fs-mono: 'JetBrains Mono', ui-monospace, Menlo, monospace;

	font-family: var(--fs-body);
	color: var(--ink);
	-webkit-font-smoothing: antialiased;
	max-width: 1180px;
	margin: 10px 0;
	font-variant-numeric: tabular-nums;
}

/* --- shared card shell ------------------------------------------------- */
.card {
	position: relative;
	background: var(--surface);
	border: 1px solid var(--line);
	border-radius: var(--r-xl);
	box-shadow: var(--sh-2);
	overflow: hidden;
}

.card__head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 12px;
	flex-wrap: wrap;
	padding: 16px 20px 13px;
	border-bottom: 1px solid var(--line-soft);
}

.card__title {
	margin: 0;
	font-family: var(--fs-display);
	font-size: 17px;
	font-weight: 500;
	letter-spacing: -0.005em;
	color: var(--ink);
}

.card__sub {
	margin: 3px 0 0;
	font-size: 11.5px;
	color: var(--ink-40);
	letter-spacing: 0.01em;
}

.card__body { padding: 16px 20px 18px; }

.link {
	font-size: 12px;
	font-weight: 700;
	color: var(--navy);
	text-decoration: none;
	white-space: nowrap;
	border-bottom: 1px solid transparent;
	transition: border-color .15s ease, color .15s ease;
}
.link:hover { color: var(--navy-700); border-bottom-color: currentColor; }

.muted { color: var(--ink-40); font-size: 12.5px; }

/* --- pills ------------------------------------------------------------- */
.pill {
	display: inline-flex;
	align-items: center;
	gap: 5px;
	padding: 3px 10px;
	border-radius: 999px;
	font-size: 11px;
	font-weight: 700;
	letter-spacing: .02em;
	background: var(--navy-50);
	color: var(--navy);
	white-space: nowrap;
}
.pill[data-tone="ok"]      { background: var(--ok-bg);     color: var(--ok); }
.pill[data-tone="warn"]    { background: var(--warn-bg);   color: var(--warn); }
.pill[data-tone="danger"]  { background: var(--danger-bg); color: var(--danger); }
.pill[data-tone="info"]    { background: var(--info-bg);   color: var(--info); }
.pill[data-tone="violet"]  { background: var(--violet-bg); color: var(--violet); }
.pill[data-tone="neutral"] { background: #f4f1ee;          color: var(--ink-60); }

/* --- entrance ---------------------------------------------------------- */
@keyframes lv-rise {
	from { opacity: 0; transform: translateY(6px); }
	to   { opacity: 1; transform: none; }
}
.rise { animation: lv-rise .42s cubic-bezier(.2,.7,.3,1) both; }

@media (prefers-reduced-motion: reduce) {
	.rise { animation: none; }
	* { transition: none !important; }
}

.lv--cal { max-width: 940px; }

.cal-nav { display: flex; align-items: center; gap: 8px; }
.cal-nav__btn {
	width: 30px; height: 30px; cursor: pointer;
	border: 1px solid var(--line); background: var(--surface);
	border-radius: var(--r-sm); color: var(--ink-60);
	font-size: 17px; line-height: 1; font-family: var(--fs-body);
	transition: background .14s ease, border-color .14s ease, color .14s ease;
}
.cal-nav__btn:hover { background: var(--navy-50); border-color: #cfdcea; color: var(--navy); }
.cal-nav__btn:focus-visible { outline: 2px solid rgba(77,73,72,.4); outline-offset: 1px; }
.cal-nav__label {
	min-width: 152px; text-align: center;
	font-size: 13.5px; font-weight: 700; color: var(--ink); letter-spacing: -.005em;
}

.cal-wd {
	display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px;
	margin-bottom: 7px;
	font-size: 10px; font-weight: 800; letter-spacing: .09em;
	text-transform: uppercase; color: var(--ink-40); text-align: center;
}
.cal-grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px; }

.cal-cell {
	position: relative; min-height: 56px;
	border: 1px solid var(--line-soft); border-radius: var(--r-md);
	background: var(--surface); padding: 6px 8px;
	transition: transform .13s ease, box-shadow .13s ease;
}
.cal-cell[data-kind]:hover { transform: translateY(-1px); box-shadow: var(--sh-2); }

.cal-cell__num { font-size: 12px; font-weight: 700; color: var(--ink-60); }
.cal-cell__dot {
	position: absolute; bottom: 8px; left: 8px;
	width: 9px; height: 9px; border-radius: 50%;
	border: 1px solid rgba(16,32,48,.14);
}
.cal-cell__hrs {
	position: absolute; bottom: 6px; right: 8px;
	font-family: var(--fs-mono); font-size: 10px; font-weight: 700; color: var(--ink-70);
}

/* the six statuses - colours fixed by HR policy, do not re-map */
.cal-cell[data-kind="present"] { background: #e7f8ef; border-color: #cdeedd; }
.cal-cell[data-kind="present"] .cal-cell__dot { background: #27ae60; }
.cal-cell[data-kind="wfh"]     { background: #e8f1fd; border-color: #cfe0f7; }
.cal-cell[data-kind="wfh"]     .cal-cell__dot { background: #2f80ed; }
.cal-cell[data-kind="half"]    { background: #f4ecfd; border-color: #e3d4f8; }
.cal-cell[data-kind="half"]    .cal-cell__dot { background: #9b51e0; }
.cal-cell[data-kind="leave"]   { background: #fff8e1; border-color: #f5e6b8; }
.cal-cell[data-kind="leave"]   .cal-cell__dot { background: #f2c94c; }
.cal-cell[data-kind="absent"]  { background: #fdeaea; border-color: #f7d2d0; }
.cal-cell[data-kind="absent"]  .cal-cell__dot { background: #e74c3c; }
.cal-cell[data-kind="off"]     { background: #faf8f5; border-color: var(--line-soft); }
.cal-cell[data-kind="off"]     .cal-cell__dot { background: #ffffff; }
.cal-cell[data-kind="off"]     .cal-cell__num { color: var(--ink-40); }

/* today: brand ring rather than a black box */
.cal-cell[data-today="1"] {
	border: 2px solid var(--navy);
	box-shadow: 0 0 0 3px rgba(77,73,72,.10);
}
.cal-cell[data-today="1"] .cal-cell__num { color: var(--navy); font-weight: 800; }

.cal-legend {
	display: flex; flex-wrap: wrap; gap: 8px 18px;
	margin-top: 18px; padding-top: 14px;
	border-top: 1px solid var(--line-soft);
	font-size: 11.5px; font-weight: 600; color: var(--ink-60);
}
.cal-legend__item { display: flex; align-items: center; gap: 7px; }
.cal-legend__swatch {
	width: 11px; height: 11px; border-radius: 50%;
	border: 1px solid rgba(16,32,48,.16); display: inline-block;
}

@media (max-width: 640px) {
	.cal-cell { min-height: 46px; padding: 5px 6px; }
	.cal-cell__hrs { display: none; }
}


/* --- lv accent identity ------------------------------------------------
   Colour-only layer on top of the existing card system: a gradient spine
   across the top of the card, a faint wash behind the header, and a hover
   lift tinted with the same hue. Every card used to be an identical white
   rectangle, which made a column of them read as one grey slab.
   Typography, spacing and layout are untouched.
   Named --lv-card-accent (not --accent) because two blocks already use
   --accent for their own internal purposes. */
.lv { --lv-card-accent: #3f4ea8; }

.card {
	transition: transform .2s cubic-bezier(.2,.7,.3,1),
	            box-shadow .2s ease,
	            border-color .2s ease;
}

.card::before {
	content: "";
	position: absolute;
	top: 0; left: 0; right: 0;
	height: 3px;
	background: linear-gradient(90deg,
		var(--lv-card-accent),
		color-mix(in srgb, var(--lv-card-accent) 32%, transparent) 70%,
		transparent);
	z-index: 2;
}

.card__head {
	background: linear-gradient(180deg,
		color-mix(in srgb, var(--lv-card-accent) 7%, #fff),
		#fff);
}

.card:hover {
	border-color: color-mix(in srgb, var(--lv-card-accent) 26%, var(--line));
	box-shadow:
		0 14px 34px color-mix(in srgb, var(--lv-card-accent) 15%, transparent),
		0 2px 8px rgba(16,32,48,.05);
}

@media (prefers-reduced-motion: reduce) {
	.card { transition: none; }
}


/* --- holiday name on the cell ------------------------------------------
   Small caption under the date number. Clipped to one line so a long name
   can never change the cell height and break the grid rhythm. */
.cal-cell__hol {
	margin-top: 1px;
	font-size: 9px;
	line-height: 1.15;
	font-weight: 700;
	letter-spacing: .01em;
	color: #221f1e;
	max-width: 100%;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}


/* --- holiday caption: keep it inside its cell -------------------------
   The cell must be allowed to shrink, otherwise the nowrap caption sets the
   grid track's min-content width and pushes the whole calendar out of
   alignment (very visible on a phone). */
.cal-cell { min-width: 0; }
.cal-cell__hol { min-width: 0; }

/* On a phone the cell is far too narrow for a truncated 9px name to be
   worth reading, so drop it there - the date still carries its holiday
   colour, and the full name remains in the cell's title tooltip. */
@media (max-width: 640px) {
	.cal-cell__hol { display: none; }
}

script:
(function () {
    // The `roles` table on a Custom HTML Block does NOT gate delivery -
    // get_custom_blocks_for_user filters only on private/owner - so every
    // employee was served the HR dashboard on Home. Hide it here instead.
    if (typeof frappe !== 'undefined' && !(frappe.user.has_role('HR Manager')
            || frappe.user.has_role('System Manager'))) {
        if (typeof root_element !== 'undefined' && root_element) {
            root_element.innerHTML = '';
            var host = root_element.host || (root_element.getRootNode && root_element.getRootNode().host);
            if (host && host.closest) {
                var blk = host.closest('.widget, .custom-block, .ce-block');
                if (blk) { blk.style.display = 'none'; }
            }
        }
        return;
    }

  setTimeout(function () {
    if (typeof frappe === 'undefined' || !root_element) return;
    var root = root_element;
    var $ = function (s) { return root.querySelector(s); };
    var empSel = $('#dash-emp'), fromEl = $('#dash-from'), toEl = $('#dash-to');
    var tilesEl = $('#dash-tiles'), headEl = $('#dash-head'), bodyEl = $('#dash-body');
    if (!bodyEl) return;

    var FULL_DAY_HOURS = 8;   // per HR policy
    var LATE_AFTER = 10 * 60 + 45;    // 10:45
    var EARLY_BEFORE = 18 * 60 + 45;  // 18:45
    var employees = [];

    function fmt(d) { return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }
    function today() { return new Date(); }
    function getList(dt, filters, fields) {
      return new Promise(function (res) {
        frappe.call({ method: 'frappe.client.get_list', args: { doctype: dt, filters: filters, fields: fields, limit_page_length: 0 }, callback: function (r) { res((r && r.message) || []); }, error: function () { res([]); } });
      });
    }
    function mins(t) { var p = String(t).slice(11, 16).split(':'); return (+p[0]) * 60 + (+p[1]); }
    function hhmm(t) { return String(t).slice(11, 16); }
    function fmtDur(sec) { var h = Math.floor(sec / 3600); var m = Math.floor((sec % 3600) / 60); return h + 'h ' + String(m).padStart(2, '0') + 'm'; }
    function daysBetween(a, b) { var out = [], d = new Date(a); while (d <= b) { out.push(new Date(d)); d.setDate(d.getDate() + 1); } return out; }
    function badge(t, c) { return '<span style="background:' + c + '18;color:' + c + ';padding:2px 8px;border-radius:20px;font-size:11px;font-weight:600;">' + t + '</span>'; }
    function tile(l, v, c) { return '<div style="background:' + c + '11;border:1px solid ' + c + '33;border-radius:10px;padding:11px 13px;"><div style="font-size:21px;font-weight:700;color:' + c + ';">' + v + '</div><div style="font-size:10.5px;color:#5c5551;text-transform:uppercase;letter-spacing:.4px;">' + l + '</div></div>'; }

    // per employee-day metrics from that day's checkin logs
    function dayMetrics(logs) {
      logs = logs.slice().sort(function (a, b) { return a.time < b.time ? -1 : 1; });
      var ins = logs.filter(function (l) { return l.log_type === 'IN'; });
      var outs = logs.filter(function (l) { return l.log_type === 'OUT'; });
      var firstIn = ins.length ? ins[0].time : null, lastOut = outs.length ? outs[outs.length - 1].time : null;
      var sec = 0, lastInT = null;
      logs.forEach(function (l) { if (l.log_type === 'IN') lastInT = new Date(l.time.replace(' ', 'T')); else if (l.log_type === 'OUT' && lastInT) { sec += (new Date(l.time.replace(' ', 'T')) - lastInT) / 1000; lastInT = null; } });
      var wfh = logs.some(function (l) { return String(l.device_id || '').toLowerCase().indexOf('home') !== -1; });
      return { wfh: wfh, in: firstIn, out: lastOut, worked: sec, late: firstIn ? mins(firstIn) > LATE_AFTER : false, early: (lastOut && (sec / 3600) < FULL_DAY_HOURS) ? true : false, has: logs.length > 0 };
    }

    function load() {
      var from = fromEl.value, to = toEl.value; if (!from || !to) return;
      if (from > to) { var t = from; from = to; to = t; }
      var empFilter = empSel.value; // "" = all
      bodyEl.innerHTML = '<tr><td colspan="8" style="padding:14px;color:#928a85;">Loading…</td></tr>';
      var empFilters = { status: 'Active' }; if (empFilter) empFilters.name = empFilter;
      Promise.all([
        getList('Employee', empFilters, ['name', 'employee_name', 'department']),
        getList('Employee Checkin', { time: ['between', [from + ' 00:00:00', to + ' 23:59:59']] }, ['employee', 'log_type', 'time', 'device_id']),
        getList('Leave Application', { status: 'Approved', docstatus: 1, from_date: ['<=', to], to_date: ['>=', from] }, ['employee', 'from_date', 'to_date']),
        getList('Attendance', { attendance_date: ['between', [from, to]], docstatus: 1 }, ['employee', 'attendance_date', 'status']),
        getList('Work From Home Request', { workflow_state: 'Approved', from_date: ['<=', to], to_date: ['>=', from] }, ['employee', 'from_date', 'to_date'])
      ]).then(function (out) {
        var emps = out[0], checkins = out[1], leaves = out[2], atts = out[3] || [], wfhReqs = out[4] || [];
        // An approved regularization writes Attendance but leaves no check-in, so a
        // dashboard built only from check-ins showed those days as absent.
        var attBy = {};
        atts.forEach(function (a) { attBy[a.employee + '|' + String(a.attendance_date)] = a.status; });
        function attStatus(emp, dateStr) { return attBy[emp + '|' + dateStr]; }
        // a day covered by an APPROVED WFH request counts as work-from-home even
        // if the check-in GPS didn't classify it that way
        function wfhApproved(emp, dateStr) {
          return wfhReqs.some(function (w) { return w.employee === emp && String(w.from_date) <= dateStr && String(w.to_date) >= dateStr; });
        }
        var byEmpDay = {};
        checkins.forEach(function (c) { var d = String(c.time).slice(0, 10); var k = c.employee + '|' + d; (byEmpDay[k] = byEmpDay[k] || []).push(c); });
        function onLeave(emp, dateStr) { return leaves.some(function (l) { return l.employee === emp && String(l.from_date) <= dateStr && String(l.to_date) >= dateStr; }); }
        var days = daysBetween(new Date(from), new Date(to));
        var tnow = new Date(); tnow.setHours(0, 0, 0, 0);
        var sum = { present: 0, late: 0, early: 0, absent: 0, leave: 0, wfh: 0 };
        var singleEmp = !!empFilter;

        if (singleEmp) {
          // day-by-day for one employee
          headEl.innerHTML = ['Date', 'Check-in', 'Check-out', 'Worked', 'Late', 'Early Exit', 'Status'].map(function (c) { return '<th style="text-align:left;padding:8px 10px;border-bottom:2px solid #edf1f5;color:#928a85;font-weight:600;white-space:nowrap;">' + c + '</th>'; }).join('');
          var rows = days.map(function (dObj) {
            var ds = fmt(dObj), weekend = dObj.getDay() === 0 || dObj.getDay() === 6;
            var m = dayMetrics(byEmpDay[empFilter + '|' + ds] || []);
            if (wfhApproved(empFilter, ds)) m.wfh = true;
            var recorded = attStatus(empFilter, ds);
            if (recorded && !m.has) {
              m.has = true;                                  // regularized / marked by HR
              if (recorded === 'Work From Home') m.wfh = true;
            }
            var st, col;
            if (onLeave(empFilter, ds)) { st = 'On Leave'; col = '#2f80ed'; sum.leave++; }
            else if (m.has) { st = m.wfh ? 'Present (WFH)' : 'Present'; col = '#27ae60'; sum.present++; if (m.wfh) sum.wfh++; if (m.late) sum.late++; if (m.early) sum.early++; }
            else if (weekend) { st = 'Week-off'; col = '#928a85'; }
            else if (dObj <= tnow) { st = 'Absent'; col = '#c0392b'; sum.absent++; }
            else { st = '—'; col = '#c3ccd4'; }
            return '<tr style="border-bottom:1px solid #f2f5f8;"><td style="padding:8px 10px;font-weight:600;color:#221f1e;white-space:nowrap;">' + ds + ' <span style="color:#9aa7b2;font-weight:400;">' + dObj.toLocaleDateString('default', { weekday: 'short' }) + '</span></td>' +
              '<td style="padding:8px 10px;">' + (m.in ? hhmm(m.in) : '—') + '</td><td style="padding:8px 10px;">' + (m.out ? hhmm(m.out) : '—') + '</td>' +
              '<td style="padding:8px 10px;font-weight:600;">' + (m.worked > 0 ? fmtDur(m.worked) : '—') + '</td>' +
              '<td style="padding:8px 10px;">' + (m.late ? badge('LATE', '#e67e22') : '') + '</td><td style="padding:8px 10px;">' + (m.early ? badge('EARLY', '#8e44ad') : '') + '</td>' +
              '<td style="padding:8px 10px;">' + badge(st, col) + '</td></tr>';
          });
          bodyEl.innerHTML = rows.join('');
        } else {
          // aggregate per employee over the range
          headEl.innerHTML = ['Employee', 'Department', 'Present', 'WFH', 'Late', 'Early Exit', 'Absent', 'On Leave'].map(function (c) { return '<th style="text-align:left;padding:8px 10px;border-bottom:2px solid #edf1f5;color:#928a85;font-weight:600;white-space:nowrap;">' + c + '</th>'; }).join('');
          var rows2 = emps.map(function (e) {
            var r = { present: 0, late: 0, early: 0, absent: 0, leave: 0, wfh: 0 };
            days.forEach(function (dObj) {
              var ds = fmt(dObj), weekend = dObj.getDay() === 0 || dObj.getDay() === 6;
              if (onLeave(e.name, ds)) { r.leave++; return; }
              var m = dayMetrics(byEmpDay[e.name + '|' + ds] || []);
              var rec = attStatus(e.name, ds);
            if (rec && !m.has) { m.has = true; if (rec === 'Work From Home') m.wfh = true; }
            if (rec === 'Absent') { m.has = false; }
            if (m.has) { r.present++; if (m.wfh || wfhApproved(e.name, ds)) r.wfh++; if (m.late) r.late++; if (m.early) r.early++; }
              else if (!weekend && dObj <= tnow) r.absent++;
            });
            sum.present += r.present; sum.late += r.late; sum.early += r.early; sum.absent += r.absent; sum.leave += r.leave; sum.wfh += r.wfh;
            return { name: e.employee_name, dept: (e.department || '').replace(' - LA', ''), r: r };
          });
          rows2.sort(function (a, b) { return b.r.late - a.r.late || (a.name < b.name ? -1 : 1); });
          bodyEl.innerHTML = rows2.map(function (x) {
            return '<tr style="border-bottom:1px solid #f2f5f8;"><td style="padding:8px 10px;font-weight:600;color:#221f1e;">' + x.name + '</td><td style="padding:8px 10px;color:#5c5551;">' + (x.dept || '—') + '</td>' +
              '<td style="padding:8px 10px;">' + x.r.present + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.wfh ? badge(x.r.wfh, '#1263d1') : '0') + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.late ? badge(x.r.late, '#e67e22') : '0') + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.early ? badge(x.r.early, '#8e44ad') : '0') + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.absent ? badge(x.r.absent, '#c0392b') : '0') + '</td>' +
              '<td style="padding:8px 10px;">' + (x.r.leave || '0') + '</td></tr>';
          }).join('') || '<tr><td colspan="8" style="padding:14px;color:#928a85;">No employees</td></tr>';
        }
        tilesEl.innerHTML = tile('Present', sum.present, '#27ae60') + tile('WFH', sum.wfh, '#1263d1') + tile('Late In', sum.late, '#e67e22') + tile('Early Out', sum.early, '#8e44ad') + tile('Absent', sum.absent, '#c0392b') + tile('On Leave', sum.leave, '#2f80ed');
      });
    }

    function setRange(a, b) { fromEl.value = fmt(a); toEl.value = fmt(b); load(); }
    $('#dash-today').onclick = function () { var d = today(); setRange(d, d); };
    $('#dash-week').onclick = function () { var d = today(), day = (d.getDay() + 6) % 7, mon = new Date(d); mon.setDate(d.getDate() - day); setRange(mon, d); };
    $('#dash-month').onclick = function () { var d = today(); setRange(new Date(d.getFullYear(), d.getMonth(), 1), d); };
    empSel.onchange = load; fromEl.onchange = load; toEl.onchange = load;

    // populate employee dropdown, then default to today
    getList('Employee', { status: 'Active' }, ['name', 'employee_name']).then(function (list) {
      employees = list;
      var opts = '<option value="">All employees</option>';
      list.sort(function (a, b) { return a.employee_name < b.employee_name ? -1 : 1; }).forEach(function (e) { opts += '<option value="' + e.name + '">' + e.employee_name + '</option>'; });
      empSel.innerHTML = opts;
      var d = today(); fromEl.value = fmt(d); toEl.value = fmt(d); load();
    });
  }, 400);
})();

style:
/* --- lv accent identity (legacy inline-styled card) --------------------
   This block predates the shared card system and styles its shell inline.
   Rather than restyle it wholesale, add only what inline styles cannot
   express: a gradient spine, and a hover lift. Layout and type untouched. */
#att-dash {
	position: relative;
	overflow: hidden;
	transition: transform .2s cubic-bezier(.2,.7,.3,1),
	            box-shadow .2s ease, border-color .2s ease;
}
#att-dash::before {
	content: "";
	position: absolute;
	top: 0; left: 0; right: 0;
	height: 3px;
	background: linear-gradient(90deg,
		#4d4948,
		color-mix(in srgb, #4d4948 32%, transparent) 70%,
		transparent);
	z-index: 2;
}
#att-dash:hover {
	border-color: color-mix(in srgb, #4d4948 26%, #e7e2dc) !important;
	box-shadow:
		0 14px 34px color-mix(in srgb, #4d4948 15%, transparent),
		0 2px 8px rgba(16,32,48,.05) !important;
}
@media (prefers-reduced-motion: reduce) { #att-dash { transition: none; } }

script:
(function () {
    setTimeout(function () {
        if (typeof frappe === 'undefined' || !root_element) return;
        var body = root_element.querySelector('#lv-leave-body');
        var sub  = root_element.querySelector('#lv-leave-sub');
        if (!body) return;
        function esc(t) { return frappe.utils.escape_html(t || ''); }

        if (frappe.session.user === 'Administrator') {
            body.innerHTML = '<div class="muted">Admin view — leave balance is shown to employees.</div>';
            return;
        }

        function sum(label, value, meta) {
            return '<div class="lb lb--sum">' +
                     '<div class="lb__label">' + label + '</div>' +
                     '<div class="lb__value">' + value + '<span class="lb__unit">days</span></div>' +
                     (meta ? '<div class="lb__meta">' + meta + '</div>' : '') +
                   '</div>';
        }

        function type(x) {
            var alloc = Number(x.allocated || 0);
            var taken = Number(x.taken || 0);
            var bal   = Number(x.balance || 0);
            var pct   = alloc > 0 ? Math.min(100, Math.round((taken / alloc) * 100)) : 0;
            var low   = alloc > 0 && bal <= Math.max(1, alloc * 0.15);
            return '<div class="lb lb--type' + (low ? ' lb--low' : '') + '">' +
                     '<div class="lb__label">' + esc(x.leave_type) + '</div>' +
                     '<div class="lb__value">' + bal + '<span class="lb__unit">left</span></div>' +
                     '<div class="lb__bar"><div class="lb__fill" style="width:' + pct + '%"></div></div>' +
                     '<div class="lb__meta">' + taken + ' of ' + alloc + ' used</div>' +
                   '</div>';
        }

        frappe.call({
            method: 'get_my_leave_balance',
            callback: function (r) {
                var d = r.message || {};
                var rows = d.rows || [];
                if (!rows.length) {
                    body.innerHTML = '<div class="muted">No leave allocated yet. Please check with HR.</div>';
                    return;
                }
                var totalLeft = rows.reduce(function (a, x) { return a + Number(x.balance || 0); }, 0);
                if (sub) sub.textContent = totalLeft + ' day' + (totalLeft === 1 ? '' : 's') + ' available in total';

                // The headline number is what you can still take. "Allocated"
                // on its own was read as the number available, and it never
                // moved as leave was used. Allocated stays as context under
                // the tile rather than as a figure of its own.
                body.innerHTML =
                    sum('Total Available Leaves', d.balance || 0,
                        'of ' + (d.allocated || 0) + ' allocated') +
                    sum('Taken', d.taken || 0) +
                    rows.map(type).join('');
            }
        });
    }, 800);
})();

style:
/* Logikview HR - shared block tokens.
   Each dashboard block renders in its own shadow root, so these tokens are
   repeated per block by design; there is no shared stylesheet to inherit from.
   Fonts come from the document-level app_include_css (font faces are not
   shadow-scoped), with a system fallback if that fails to load. */
:host { display: block; }
*, *::before, *::after { box-sizing: border-box; }

.lv {
	--navy: #4d4948;
	--navy-700: #3a3736;
	--navy-50: #f4f1ee;
	--amber: #d98d0e;
	--amber-50: #fdf5e2;

	--ink: #221f1e;
	--ink-70: #4a4441;
	--ink-60: #5c5551;
	--ink-40: #928a85;
	--line: #e7e2dc;
	--line-soft: #f1ede8;
	--surface: #ffffff;

	--ok: #17794f;      --ok-bg: #e7f5ee;
	--warn: #a86412;    --warn-bg: #fdf5e2;
	--danger: #b3261e;  --danger-bg: #fdecea;
	--info: #4d4948;    --info-bg: #f4f1ee;
	--violet: #5b43c9;  --violet-bg: #eeeaff;

	--r-xl: 18px;
	--r-lg: 14px;
	--r-md: 10px;
	--r-sm: 7px;

	--sh-1: 0 1px 2px rgba(16,32,48,.05);
	--sh-2: 0 4px 16px rgba(16,32,48,.07), 0 1px 3px rgba(16,32,48,.04);
	--sh-3: 0 16px 40px rgba(16,32,48,.12);

	--fs-display: 'Fraunces', Georgia, serif;
	--fs-body: 'Manrope', ui-sans-serif, system-ui, -apple-system, sans-serif;
	--fs-mono: 'JetBrains Mono', ui-monospace, Menlo, monospace;

	font-family: var(--fs-body);
	color: var(--ink);
	-webkit-font-smoothing: antialiased;
	max-width: 1180px;
	margin: 10px 0;
	font-variant-numeric: tabular-nums;
}

/* --- shared card shell ------------------------------------------------- */
.card {
	position: relative;
	background: var(--surface);
	border: 1px solid var(--line);
	border-radius: var(--r-xl);
	box-shadow: var(--sh-2);
	overflow: hidden;
}

.card__head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 12px;
	flex-wrap: wrap;
	padding: 16px 20px 13px;
	border-bottom: 1px solid var(--line-soft);
}

.card__title {
	margin: 0;
	font-family: var(--fs-display);
	font-size: 17px;
	font-weight: 500;
	letter-spacing: -0.005em;
	color: var(--ink);
}

.card__sub {
	margin: 3px 0 0;
	font-size: 11.5px;
	color: var(--ink-40);
	letter-spacing: 0.01em;
}

.card__body { padding: 16px 20px 18px; }

.link {
	font-size: 12px;
	font-weight: 700;
	color: var(--navy);
	text-decoration: none;
	white-space: nowrap;
	border-bottom: 1px solid transparent;
	transition: border-color .15s ease, color .15s ease;
}
.link:hover { color: var(--navy-700); border-bottom-color: currentColor; }

.muted { color: var(--ink-40); font-size: 12.5px; }

/* --- pills ------------------------------------------------------------- */
.pill {
	display: inline-flex;
	align-items: center;
	gap: 5px;
	padding: 3px 10px;
	border-radius: 999px;
	font-size: 11px;
	font-weight: 700;
	letter-spacing: .02em;
	background: var(--navy-50);
	color: var(--navy);
	white-space: nowrap;
}
.pill[data-tone="ok"]      { background: var(--ok-bg);     color: var(--ok); }
.pill[data-tone="warn"]    { background: var(--warn-bg);   color: var(--warn); }
.pill[data-tone="danger"]  { background: var(--danger-bg); color: var(--danger); }
.pill[data-tone="info"]    { background: var(--info-bg);   color: var(--info); }
.pill[data-tone="violet"]  { background: var(--violet-bg); color: var(--violet); }
.pill[data-tone="neutral"] { background: #f4f1ee;          color: var(--ink-60); }

/* --- entrance ---------------------------------------------------------- */
@keyframes lv-rise {
	from { opacity: 0; transform: translateY(6px); }
	to   { opacity: 1; transform: none; }
}
.rise { animation: lv-rise .42s cubic-bezier(.2,.7,.3,1) both; }

@media (prefers-reduced-motion: reduce) {
	.rise { animation: none; }
	* { transition: none !important; }
}

.lb-grid {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(196px, 1fr));
	gap: 12px;
}

.lb {
	position: relative;
	padding: 14px 16px 15px;
	border-radius: var(--r-lg);
	border: 1px solid var(--line);
	background: var(--surface);
	box-shadow: var(--sh-1);
}

.lb__label {
	font-size: 10.5px; font-weight: 800; letter-spacing: .08em;
	text-transform: uppercase; color: var(--ink-40);
}
.lb__value {
	display: flex; align-items: baseline; gap: 6px; margin-top: 7px;
	font-family: var(--fs-mono); font-size: 27px; font-weight: 700;
	line-height: 1; letter-spacing: -.02em; color: var(--ink);
}
.lb__unit { font-family: var(--fs-body); font-size: 11.5px; font-weight: 700; color: var(--ink-40); }
.lb__meta { margin-top: 7px; font-size: 11px; color: var(--ink-40); }

/* a leave type: value is what's left, bar shows how much is gone */
.lb--type { border-color: #d9e6f2; background: linear-gradient(180deg,#fbfdff 0%,#f4f9fd 100%); }
.lb--type .lb__label { color: var(--navy); }

.lb__bar {
	margin-top: 10px; height: 5px; border-radius: 999px;
	background: #dde7f0; overflow: hidden;
}
.lb__fill {
	height: 100%; border-radius: 999px;
	background: linear-gradient(90deg, var(--navy) 0%, #3f7fb5 100%);
	transition: width .5s cubic-bezier(.2,.7,.3,1);
}
.lb--low .lb__fill { background: linear-gradient(90deg,#b3261e 0%,#d9534a 100%); }
.lb--low .lb__value { color: var(--danger); }

/* the two roll-up tiles read quieter than the per-type ones */
.lb--sum { background: #faf8f5; }


/* --- lv accent identity ------------------------------------------------
   Colour-only layer on top of the existing card system: a gradient spine
   across the top of the card, a faint wash behind the header, and a hover
   lift tinted with the same hue. Every card used to be an identical white
   rectangle, which made a column of them read as one grey slab.
   Typography, spacing and layout are untouched.
   Named --lv-card-accent (not --accent) because two blocks already use
   --accent for their own internal purposes. */
.lv { --lv-card-accent: #0f766e; }

.card {
	transition: transform .2s cubic-bezier(.2,.7,.3,1),
	            box-shadow .2s ease,
	            border-color .2s ease;
}

.card::before {
	content: "";
	position: absolute;
	top: 0; left: 0; right: 0;
	height: 3px;
	background: linear-gradient(90deg,
		var(--lv-card-accent),
		color-mix(in srgb, var(--lv-card-accent) 32%, transparent) 70%,
		transparent);
	z-index: 2;
}

.card__head {
	background: linear-gradient(180deg,
		color-mix(in srgb, var(--lv-card-accent) 7%, #fff),
		#fff);
}

.card:hover {
	border-color: color-mix(in srgb, var(--lv-card-accent) 26%, var(--line));
	box-shadow:
		0 14px 34px color-mix(in srgb, var(--lv-card-accent) 15%, transparent),
		0 2px 8px rgba(16,32,48,.05);
}

@media (prefers-reduced-motion: reduce) {
	.card { transition: none; }
}

script:
(function () {
    setTimeout(function () {
        if (typeof frappe === 'undefined' || !root_element) return;
        var body = root_element.querySelector('#lv-cel-body');
        if (!body) return;
        function esc(t) { return frappe.utils.escape_html(t || ''); }

        var EMPTY = '<div class="muted">No birthdays or work anniversaries today or tomorrow.</div>';

        function card(x, isToday) {
            var cake = x.kind === 'birthday';
            var icon = cake ? '\u{1F382}' : '\u{1F389}';
            // birthday = warm rose, anniversary = brand navy
            var vars = cake
                ? '--accent:#c2255c;--accent-bg:#fdeef3;--accent-ring:rgba(194,37,92,.22);'
                : '--accent:#4d4948;--accent-bg:#f4f1ee;--accent-ring:rgba(31,78,120,.22);';
            var sub = cake ? 'Birthday'
                           : (x.years + ' year' + (x.years > 1 ? 's' : '') + ' at Logikview');
            var when = x.is_today ? 'Today'
                     : (x.days_away === 1 ? 'Tomorrow' : frappe.datetime.str_to_user(x.date));
            return '<div class="cel" data-today="' + (isToday ? 1 : 0) + '" style="' + vars + '">' +
                     '<span class="cel__icon">' + icon + '</span>' +
                     '<span class="cel__text">' +
                       '<div class="cel__name">' + esc(x.employee_name) + '</div>' +
                       '<div class="cel__what">' + sub + '</div>' +
                       '<div class="cel__when">' + when +
                         (x.designation ? ' · ' + esc(x.designation) : '') + '</div>' +
                     '</span>' +
                   '</div>';
        }

        function group(title, list, isToday, note) {
            if (!list.length) return '';
            return '<div class="cel-group">' +
                     '<div class="cel-group__label"><b>' + title + '</b>' +
                       (note ? '<span class="cel-group__note">' + note + '</span>' : '') +
                     '</div>' +
                     '<div class="cel-row">' +
                       list.map(function (x) { return card(x, isToday); }).join('') +
                     '</div>' +
                   '</div>';
        }

        frappe.call({
            method: 'get_team_celebrations',
            callback: function (r) {
                var rows = r.message || [];
                if (!rows.length) { body.innerHTML = EMPTY; return; }
                var todays    = rows.filter(function (x) { return x.days_away === 0; });
                var tomorrows = rows.filter(function (x) { return x.days_away === 1; });
                // only today and the day before - a month-ahead list buried what
                // actually needed attention
                body.innerHTML = (group('Today', todays, true) +
                                  group('Tomorrow', tomorrows, false, 'wish them in advance')) || EMPTY;
            }
        });
    }, 700);
})();

