script:
(function () {
    setTimeout(function () {
        if (typeof frappe === 'undefined' || !root_element) return;
        var body = root_element.querySelector('#lv-hol-body');
        if (!body) return;
        var y = new Date().getFullYear();
        var yearEl = root_element.querySelector('#lv-hol-year');
        var nextEl = root_element.querySelector('#lv-hol-next');
        if (yearEl) yearEl.textContent = 'Company holidays for ' + y;

        frappe.call({
            method: 'get_my_holidays',
            args: { from_date: y + '-01-01', to_date: y + '-12-31' },
            callback: function (r) {
                var rows = (r.message || []).filter(function (h) { return !h.weekly_off; });
                if (!rows.length) {
                    body.innerHTML = '<div class="muted">No holidays configured.</div>';
                    return;
                }
                rows.sort(function (a, b) { return a.date < b.date ? -1 : 1; });
                var todayStr = frappe.datetime.get_today();

                // first one still ahead of us gets the highlight
                var nextIdx = -1;
                for (var i = 0; i < rows.length; i++) {
                    if (rows[i].date >= todayStr) { nextIdx = i; break; }
                }
                if (nextEl) {
                    if (nextIdx === -1) { nextEl.style.display = 'none'; }
                    else {
                        var nd = new Date(rows[nextIdx].date + 'T00:00:00');
                        nextEl.textContent = 'Next · ' +
                            frappe.utils.escape_html(rows[nextIdx].description || 'Holiday') +
                            ', ' + nd.toLocaleDateString('default', { day: 'numeric', month: 'short' });
                    }
                }

                body.innerHTML = rows.map(function (h, i) {
                    var past = h.date < todayStr;
                    var dt = new Date(h.date + 'T00:00:00');
                    var mon = dt.toLocaleDateString('default', { month: 'short' });
                    var day = dt.getDate();
                    var wd  = dt.toLocaleDateString('default', { weekday: 'long' });
                    return '<div class="hol" data-past="' + (past ? 1 : 0) + '"' +
                                ' data-next="' + (i === nextIdx ? 1 : 0) + '">' +
                             '<span class="hol__date">' +
                               '<span class="hol__mon">' + mon + '</span>' +
                               '<span class="hol__day">' + day + '</span>' +
                             '</span>' +
                             '<span class="hol__text">' +
                               '<div class="hol__name">' +
                                 frappe.utils.escape_html(h.description || 'Holiday') + '</div>' +
                               '<div class="hol__meta">' + wd + '</div>' +
                             '</span>' +
                           '</div>';
                }).join('');
            }
        });
    }, 700);
})();

