script:
(function () {
    setTimeout(function () {
        if (typeof frappe === 'undefined' || !root_element) return;
        var host = root_element.querySelector('#lv-oc');
        if (!host) return;
        function esc(t) { return frappe.utils.escape_html(t || ''); }

        var LINE = '#cfd8e1';

        frappe.call({
            method: 'get_org_chart',
            callback: function (r) {
                var rows = r.message || [];
                if (!rows.length) { host.innerHTML = '<div style="color:#928a85;">No employees.</div>'; return; }

                var byId = {}, kids = {};
                rows.forEach(function (e) { byId[e.name] = e; kids[e.name] = []; });
                var roots = [];
                rows.forEach(function (e) {
                    if (e.reports_to && kids[e.reports_to]) kids[e.reports_to].push(e);
                    else roots.push(e);
                });

                // ancestors[] tells us, for each level above, whether that branch
                // continues below - so we know to draw a through-line or a blank
                function guides(ancestors, isLast) {
                    var g = '';
                    ancestors.forEach(function (more) {
                        g += '<span style="display:inline-block;width:26px;height:100%;' +
                             (more ? 'border-left:1.5px solid ' + LINE + ';' : '') + '"></span>';
                    });
                    g += '<span style="display:inline-block;width:26px;align-self:stretch;position:relative;">' +
                         '<span style="position:absolute;left:0;top:0;height:' + (isLast ? '50%' : '100%') +
                         ';border-left:1.5px solid ' + LINE + ';"></span>' +
                         '<span style="position:absolute;left:0;top:50%;width:18px;' +
                         'border-top:1.5px solid ' + LINE + ';"></span></span>';
                    return g;
                }

                function card(e, depth) {
                    var n = (kids[e.name] || []).length;
                    var initials = (e.employee_name || '?').split(' ')
                        .map(function (w) { return w[0]; }).join('').slice(0, 2).toUpperCase();
                    var tone = depth === 0 ? '#4d4948' : (depth === 1 ? '#2b6ca3' : '#5b7c99');
                    var second = (e.reports_to_2 && byId[e.reports_to_2])
                        ? '<span style="font-size:10px;color:#928a85;margin-left:8px;">also &rarr; ' +
                          esc(byId[e.reports_to_2].employee_name) + '</span>' : '';
                    return '<span data-id="' + e.name + '" ' +
                        'style="display:inline-flex;align-items:center;gap:11px;' +
                        'border:1px solid ' + (e.is_me ? '#17794f' : '#e5ebf1') + ';border-radius:10px;' +
                        'background:' + (e.is_me ? '#e9f8f0' : '#fff') + ';padding:9px 14px;' +
                        'white-space:nowrap;box-shadow:0 1px 2px rgba(0,0,0,0.04);' +
                        (n ? 'cursor:pointer;' : '') + '">' +
                        '<span style="width:32px;height:32px;border-radius:50%;background:' + tone + ';color:#fff;' +
                        'display:inline-flex;align-items:center;justify-content:center;font-size:11.5px;' +
                        'font-weight:700;flex:0 0 32px;">' + initials + '</span>' +
                        '<span style="display:inline-block;line-height:1.35;">' +
                          '<span style="display:block;font-size:13px;font-weight:700;color:#221f1e;">' +
                            esc(e.employee_name) + (e.is_me ? ' (you)' : '') + '</span>' +
                          '<span style="display:block;font-size:11px;color:#6b7885;">' +
                            esc(e.designation || '-') +
                            (e.department ? ' &middot; ' + esc(e.department) : '') + '</span>' +
                        '</span>' +
                        (n ? '<span data-count="' + e.name + '" style="background:#eef3f8;color:#4c5b68;' +
                             'border-radius:10px;padding:2px 9px;font-size:11px;font-weight:700;">' +
                             n + '</span>' : '') +
                        second + '</span>';
                }

                var out = [];
                function walk(list, ancestors) {
                    list.forEach(function (e, i) {
                        var isLast = i === list.length - 1;
                        var depth = ancestors.length;
                        out.push('<div data-row="' + e.name + '" style="display:flex;align-items:stretch;' +
                                 'min-height:52px;">' +
                                 (depth ? guides(ancestors, isLast) : '') +
                                 '<span style="display:flex;align-items:center;padding:5px 0;">' +
                                 card(e, depth) + '</span></div>');
                        var children = kids[e.name] || [];
                        if (children.length) {
                            out.push('<div data-sub="' + e.name + '">');
                            walk(children, ancestors.concat([!isLast]));
                            out.push('</div>');
                        }
                    });
                }
                walk(roots, []);
                host.innerHTML = out.join('');

                host.querySelectorAll('[data-id]').forEach(function (el) {
                    el.onclick = function () {
                        var id = el.getAttribute('data-id');
                        var sub = host.querySelector('[data-sub="' + id + '"]');
                        if (!sub) return;
                        var hidden = sub.style.display === 'none';
                        sub.style.display = hidden ? '' : 'none';
                        var c = host.querySelector('[data-count="' + id + '"]');
                        if (c) {
                            c.style.background = hidden ? '#eef3f8' : '#4d4948';
                            c.style.color = hidden ? '#4c5b68' : '#fff';
                        }
                    };
                });
            }
        });
    }, 700);
})();

