script:
(function () {
    setTimeout(function () {
        if (typeof frappe === 'undefined' || !root_element) return;
        var body = root_element.querySelector('#lm-body');
        var head = root_element.querySelector('#lm-head');
        var totalEl = root_element.querySelector('#lm-total');
        if (!body) return;
        function esc(t) { return frappe.utils.escape_html(t || ''); }

        var DATA = [];

        function draw(filter) {
            var rows = DATA.filter(function (e) {
                if (!filter) return true;
                var f = filter.toLowerCase();
                return (e.employee_name || '').toLowerCase().indexOf(f) !== -1 ||
                       (e.department || '').toLowerCase().indexOf(f) !== -1;
            });

            head.innerHTML = ['Employee', 'Department', 'Leave Type', 'Allocated', 'Taken', 'Balance']
                .map(function (c) {
                    return '<th style="text-align:left;padding:8px 10px;border-bottom:2px solid #edf1f5;' +
                           'color:#928a85;font-weight:600;white-space:nowrap;">' + c + '</th>';
                }).join('');

            body.innerHTML = rows.map(function (e) {
                var nameLink = '<a href="/app/employee/' + encodeURIComponent(e.employee) +
                    '" style="color:#221f1e;text-decoration:none;">' + esc(e.employee_name) + '</a>';
                if (!e.rows.length) {
                    return '<tr style="border-bottom:1px solid #f2f5f8;">' +
                        '<td style="padding:8px 10px;font-weight:600;">' + nameLink + '</td>' +
                        '<td style="padding:8px 10px;color:#5c5551;">' + esc(e.department || '—') + '</td>' +
                        '<td colspan="4" style="padding:8px 10px;color:#c0392b;">No leave allocated</td></tr>';
                }
                return e.rows.map(function (r, i) {
                    var low = r.balance <= 2;
                    return '<tr style="border-bottom:1px solid #f2f5f8;">' +
                        '<td style="padding:8px 10px;font-weight:600;">' +
                          (i === 0 ? nameLink : '') + '</td>' +
                        '<td style="padding:8px 10px;color:#5c5551;">' +
                          (i === 0 ? esc(e.department || '—') : '') + '</td>' +
                        '<td style="padding:8px 10px;">' + esc(r.leave_type) + '</td>' +
                        '<td style="padding:8px 10px;">' + r.allocated + '</td>' +
                        '<td style="padding:8px 10px;">' + r.taken + '</td>' +
                        '<td style="padding:8px 10px;font-weight:700;color:' +
                          (low ? '#c0392b' : '#17794f') + ';">' + r.balance + '</td></tr>';
                }).join('');
            }).join('') || '<tr><td colspan="6" style="padding:14px;color:#928a85;">No employees yet.</td></tr>';

        }


        frappe.call({
            method: 'get_team_leave_balance',
            callback: function (r) {
                var m = r.message;
                if (!m || m.error) {
                    body.innerHTML = '<tr><td style="padding:14px;color:#928a85;">' +
                                     'This view is for HR only.</td></tr>';
                    return;
                }
                DATA = m;
                if (totalEl) totalEl.textContent = DATA.length + ' employee' + (DATA.length === 1 ? '' : 's');
                draw();
            }
        });
    }, 700);
})();

