script:
(function () {
    setTimeout(function () {
        if (typeof frappe === 'undefined' || !root_element) return;
        var host = root_element.querySelector('#lv-appr');
        if (!host) return;
        function esc(t) { return frappe.utils.escape_html(t || ''); }
        function nl(t) { return esc(t).replace(/\n/g, '<br>'); }

        // workflow state -> pill tone (tones live in the shared token CSS)
        var TONE = {
            'Pending Self-Assessment': 'warn',
            'Pending Manager Review':  'warn',
            'Pending Director Review': 'info',
            'Pending Final Director':  'info',
            'Completed':               'ok'
        };
        function pill(state) {
            return '<span class="pill" data-tone="' + (TONE[state] || 'neutral') + '">' +
                   esc(state) + '</span>';
        }
        function box(title, text, accent) {
            if (!text) return '';
            return '<div class="ap-box" style="--accent:' + accent + '">' +
                     '<div class="ap-box__label">' + title + '</div>' +
                     '<div class="ap-box__text">' + nl(text) + '</div>' +
                   '</div>';
        }
        function score(label, v) {
            return '<div class="ap-score">' +
                     '<div class="ap-score__label">' + label + '</div>' +
                     '<div class="ap-score__value">' +
                       (v == null ? '—' : v + '<small> / 5</small>') + '</div>' +
                   '</div>';
        }

        frappe.call({
            method: 'get_my_appraisal',
            callback: function (r) {
                var m = r.message || {};
                var a = m.mine;
                var out = '';

                if (!a) {
                    out += '<div class="muted">You do not have an appraisal yet. ' +
                           'One is created automatically 7 days before your work anniversary.</div>';
                } else {
                    var hasFeedback = a.ro_feedback || a.first_director_feedback || a.second_director_feedback;
                    out += '<div class="ap-top">' +
                             '<span class="ap-who">' + esc(a.employee_name) + '</span>' +
                             pill(a.workflow_state) +
                             (a.years_completed ? '<span class="ap-cycle">' + a.years_completed +
                                                  '-year review</span>' : '') +
                           '</div>' +
                           '<div class="ap-scores">' + score('Self', a.self_avg) +
                             score('Manager', a.ro_avg) + '</div>';

                    out += box('Goals for the coming year', a.q_goals, '#4d4948');
                    out += box('Manager feedback' +
                               (a.reporting_officer_name ? ' · ' + esc(a.reporting_officer_name) : ''),
                               a.ro_feedback, '#5b43c9');
                    out += box('Director feedback', a.first_director_feedback, '#17794f');
                    out += box('Final director feedback', a.second_director_feedback, '#17794f');

                    if (!hasFeedback && !a.q_goals) {
                        out += '<div class="muted" style="margin-top:11px;">No feedback or goals recorded yet — ' +
                               'they appear here as your appraisal progresses.</div>';
                    }
                    out += '<a class="link ap-open" href="/app/logikview-appraisal/' + a.name +
                           '">Open my appraisal &rsaquo;</a>';
                }

                if (m.is_hr && (m.team || []).length) {
                    out += '<div class="ap-team">' +
                             '<div class="ap-team__label">Team appraisals</div>' +
                             '<div class="ap-scroll"><table class="ap-table"><thead><tr>' +
                               ['Employee','Status','Goals set','Manager feedback','Director feedback']
                                 .map(function (c) { return '<th>' + c + '</th>'; }).join('') +
                             '</tr></thead><tbody>' +
                             m.team.map(function (t) {
                                 function tick(v) {
                                     return '<span class="tick" data-yes="' + (v ? 1 : 0) + '">' +
                                            (v ? 'Yes' : 'No') + '</span>';
                                 }
                                 return '<tr>' +
                                          '<td><a href="/app/logikview-appraisal/' + t.name + '">' +
                                            esc(t.employee_name) + '</a></td>' +
                                          '<td>' + pill(t.workflow_state) + '</td>' +
                                          '<td>' + tick(t.q_goals) + '</td>' +
                                          '<td>' + tick(t.ro_feedback) + '</td>' +
                                          '<td>' + tick(t.first_director_feedback ||
                                                        t.second_director_feedback) + '</td>' +
                                        '</tr>';
                             }).join('') +
                             '</tbody></table></div></div>';
                }
                host.innerHTML = out;
            }
        });
    }, 700);
})();

style:
/* Logikview HR - shared block tokens.
   Each dashboard block renders in its own shadow root, so these tokens are
   repeated per block by design; there is no shared stylesheet to inherit from.
   Fonts come from the document-level app_include_css (font faces are not
   shadow-scoped), with a system fallback if that fails to load. */
:host { display: block; }
*, *::before, *::after { box-sizing: border-box; }

.lv {
	--navy: #4d4948;
	--navy-700: #3a3736;
	--navy-50: #f4f1ee;
	--amber: #d98d0e;
	--amber-50: #fdf5e2;

	--ink: #221f1e;
	--ink-70: #4a4441;
	--ink-60: #5c5551;
	--ink-40: #928a85;
	--line: #e7e2dc;
	--line-soft: #f1ede8;
	--surface: #ffffff;

	--ok: #17794f;      --ok-bg: #e7f5ee;
	--warn: #a86412;    --warn-bg: #fdf5e2;
	--danger: #b3261e;  --danger-bg: #fdecea;
	--info: #4d4948;    --info-bg: #f4f1ee;
	--violet: #5b43c9;  --violet-bg: #eeeaff;

	--r-xl: 18px;
	--r-lg: 14px;
	--r-md: 10px;
	--r-sm: 7px;

	--sh-1: 0 1px 2px rgba(16,32,48,.05);
	--sh-2: 0 4px 16px rgba(16,32,48,.07), 0 1px 3px rgba(16,32,48,.04);
	--sh-3: 0 16px 40px rgba(16,32,48,.12);

	--fs-display: 'Fraunces', Georgia, serif;
	--fs-body: 'Manrope', ui-sans-serif, system-ui, -apple-system, sans-serif;
	--fs-mono: 'JetBrains Mono', ui-monospace, Menlo, monospace;

	font-family: var(--fs-body);
	color: var(--ink);
	-webkit-font-smoothing: antialiased;
	max-width: 1180px;
	margin: 10px 0;
	font-variant-numeric: tabular-nums;
}

/* --- shared card shell ------------------------------------------------- */
.card {
	position: relative;
	background: var(--surface);
	border: 1px solid var(--line);
	border-radius: var(--r-xl);
	box-shadow: var(--sh-2);
	overflow: hidden;
}

.card__head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 12px;
	flex-wrap: wrap;
	padding: 16px 20px 13px;
	border-bottom: 1px solid var(--line-soft);
}

.card__title {
	margin: 0;
	font-family: var(--fs-display);
	font-size: 17px;
	font-weight: 500;
	letter-spacing: -0.005em;
	color: var(--ink);
}

.card__sub {
	margin: 3px 0 0;
	font-size: 11.5px;
	color: var(--ink-40);
	letter-spacing: 0.01em;
}

.card__body { padding: 16px 20px 18px; }

.link {
	font-size: 12px;
	font-weight: 700;
	color: var(--navy);
	text-decoration: none;
	white-space: nowrap;
	border-bottom: 1px solid transparent;
	transition: border-color .15s ease, color .15s ease;
}
.link:hover { color: var(--navy-700); border-bottom-color: currentColor; }

.muted { color: var(--ink-40); font-size: 12.5px; }

/* --- pills ------------------------------------------------------------- */
.pill {
	display: inline-flex;
	align-items: center;
	gap: 5px;
	padding: 3px 10px;
	border-radius: 999px;
	font-size: 11px;
	font-weight: 700;
	letter-spacing: .02em;
	background: var(--navy-50);
	color: var(--navy);
	white-space: nowrap;
}
.pill[data-tone="ok"]      { background: var(--ok-bg);     color: var(--ok); }
.pill[data-tone="warn"]    { background: var(--warn-bg);   color: var(--warn); }
.pill[data-tone="danger"]  { background: var(--danger-bg); color: var(--danger); }
.pill[data-tone="info"]    { background: var(--info-bg);   color: var(--info); }
.pill[data-tone="violet"]  { background: var(--violet-bg); color: var(--violet); }
.pill[data-tone="neutral"] { background: #f4f1ee;          color: var(--ink-60); }

/* --- entrance ---------------------------------------------------------- */
@keyframes lv-rise {
	from { opacity: 0; transform: translateY(6px); }
	to   { opacity: 1; transform: none; }
}
.rise { animation: lv-rise .42s cubic-bezier(.2,.7,.3,1) both; }

@media (prefers-reduced-motion: reduce) {
	.rise { animation: none; }
	* { transition: none !important; }
}

.ap-top { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.ap-who { font-size: 15px; font-weight: 700; color: var(--ink); letter-spacing: -.005em; }
.ap-cycle { font-size: 11.5px; color: var(--ink-40); }

.ap-scores { display: flex; gap: 10px; margin-top: 13px; flex-wrap: wrap; }
.ap-score {
	min-width: 116px; padding: 11px 14px;
	border-radius: var(--r-lg); border: 1px solid var(--line); background: #faf8f5;
}
.ap-score__label {
	font-size: 10px; font-weight: 800; letter-spacing: .08em;
	text-transform: uppercase; color: var(--ink-40);
}
.ap-score__value {
	margin-top: 5px; font-family: var(--fs-mono); font-size: 22px;
	font-weight: 700; line-height: 1; color: var(--ink);
}
.ap-score__value small { font-family: var(--fs-body); font-size: 11px; color: var(--ink-40); font-weight: 700; }

.ap-box {
	margin-top: 11px; padding: 12px 14px;
	border-radius: var(--r-md);
	border-left: 3px solid var(--accent, var(--navy));
	background: #fafcfe;
}
.ap-box__label {
	font-size: 10px; font-weight: 800; letter-spacing: .08em;
	text-transform: uppercase; color: var(--accent, var(--navy)); margin-bottom: 5px;
}
.ap-box__text { font-size: 13px; line-height: 1.6; color: var(--ink-70); }

.ap-open { display: inline-block; margin-top: 14px; }

.ap-team { margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--line-soft); }
.ap-team__label {
	font-size: 10.5px; font-weight: 800; letter-spacing: .09em;
	text-transform: uppercase; color: var(--ink-40); margin-bottom: 9px;
}
.ap-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.ap-table th {
	text-align: left; padding: 7px 10px; font-size: 10px; font-weight: 800;
	letter-spacing: .07em; text-transform: uppercase; color: var(--ink-40);
	border-bottom: 1px solid var(--line);
}
.ap-table td { padding: 9px 10px; border-bottom: 1px solid var(--line-soft); }
.ap-table tr:last-child td { border-bottom: 0; }
.ap-table tbody tr { transition: background .14s ease; }
.ap-table tbody tr:hover { background: #f8fafc; }
.ap-table a { color: var(--ink); font-weight: 700; text-decoration: none; }
.ap-table a:hover { color: var(--navy); }
.tick { font-weight: 700; }
.tick[data-yes="1"] { color: var(--ok); }
.tick[data-yes="0"] { color: var(--ink-40); }
.ap-scroll { overflow-x: auto; }


/* --- lv accent identity ------------------------------------------------
   Colour-only layer on top of the existing card system: a gradient spine
   across the top of the card, a faint wash behind the header, and a hover
   lift tinted with the same hue. Every card used to be an identical white
   rectangle, which made a column of them read as one grey slab.
   Typography, spacing and layout are untouched.
   Named --lv-card-accent (not --accent) because two blocks already use
   --accent for their own internal purposes. */
.lv { --lv-card-accent: #a8384f; }

.card {
	transition: transform .2s cubic-bezier(.2,.7,.3,1),
	            box-shadow .2s ease,
	            border-color .2s ease;
}

.card::before {
	content: "";
	position: absolute;
	top: 0; left: 0; right: 0;
	height: 3px;
	background: linear-gradient(90deg,
		var(--lv-card-accent),
		color-mix(in srgb, var(--lv-card-accent) 32%, transparent) 70%,
		transparent);
	z-index: 2;
}

.card__head {
	background: linear-gradient(180deg,
		color-mix(in srgb, var(--lv-card-accent) 7%, #fff),
		#fff);
}

.card:hover {
	border-color: color-mix(in srgb, var(--lv-card-accent) 26%, var(--line));
	box-shadow:
		0 14px 34px color-mix(in srgb, var(--lv-card-accent) 15%, transparent),
		0 2px 8px rgba(16,32,48,.05);
}

@media (prefers-reduced-motion: reduce) {
	.card { transition: none; }
}
